import assert from 'node:assert/strict';
import {XIAN_2026_ARCHIVED_YINGCAI_POLICY_RECORDS as added} from '../src/data/xian2026ArchivedYingcai.ts';
import {TALENT_POLICY_RECORDS} from '../src/data/talentPolicyRecords.ts';
import {TALENT_HOUSING_RECORDS} from '../src/data/talentHousingRecords.ts';
import {GUIZHOU_POLICY_RECORDS} from '../src/data/guizhouPolicyRecords.ts';
import {GUIZHOU_HOUSING_RECORDS} from '../src/data/guizhouHousingRecords.ts';
import {assessPolicy} from '../src/data/talentQuality.ts';
const p=added[0];
assert.equal(added.length,1,'old PR #153 contained mostly already integrated records');
assert.equal(p.id,'sn-xian-english-plan-2026');
assert.equal(p.city,'西安');
assert.equal(p.temporal,'past-window');
assert.equal(p.deadline,'2026-09-30');
assert.equal(p.sourceUrl,'https://xetdz.xa.gov.cn/xwzx/tzgg/2098318571781300225.html');
assert.equal(p.applicationUrl,undefined,'closed call cannot link to an unverified application form');
assert.ok(p.reviewNote?.includes('截止')&&p.materials?.length>=4&&p.applicationSteps?.length>=4);
assert.equal(assessPolicy(p,'2026-11-06').grade,'C','expired cohort must not appear open');
assert.equal(TALENT_POLICY_RECORDS.filter(x=>x.id===p.id).length,1);
assert.equal(TALENT_POLICY_RECORDS.filter(x=>x.city==='西安'&&x.title.includes('西安英才计划')).length,1);
assert.equal(GUIZHOU_POLICY_RECORDS.filter(x=>x.city==='贵阳').length,9);
assert.equal(GUIZHOU_HOUSING_RECORDS.filter(x=>x.city==='贵阳').length,4);
assert.equal(TALENT_HOUSING_RECORDS.filter(x=>x.id==='sn-xian-abcd-talent-housing-202609').length,0,'old notice is already in Shaanxi policy rather than a new vacant house');
console.log('XI_AN_2026_ARCHIVED_YINGCAI_DEDUP_OK: 1 net-new closed cohort; old Guiyang and Yinchuan entries not duplicated');
